class TerraformState:
    def __init__(self):
        self.resources = {}

    def plan(self, desired):
        changes = []
        for name, attrs in desired.items():
            if name not in self.resources:
                changes.append(f"create {name}")
            elif self.resources[name] != attrs:
                changes.append(f"update {name}")
        return changes

    def apply(self, desired):
        changes = self.plan(desired)
        self.resources.update(desired)
        return changes


state = TerraformState()
desired = {"aws_instance.web": {"ami": "ami-0123", "instance_type": "t2.micro"}}

print("plan 1:", state.apply(desired))
print("plan 2:", state.plan(desired))
